-- Detail pages for the Capital Square product rows (editable in Admin › Trang nội dung).
-- Facts from capitalsquare.vn and cafeland.vn; existing pages are left alone.

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/capital-square/can-ho', 'PAGE', 'Căn hộ tại Capital Square', 'CAPITAL SQUARE · CĂN HỘ', 'Căn hộ 1, 2, 3 phòng ngủ và Dual Key trong quần thể 14 tòa tháp bên bờ Đông sông Hàn, giữa cầu Rồng và cầu Sông Hàn.', 'Căn 1–3 phòng ngủ và Dual Key bên sông Hàn.', '[{"heading": "Các loại căn", "body": "- Căn 1 phòng ngủ: khoảng 34,1–47,7 m²\n- Căn 2 phòng ngủ: khoảng 67–93 m²\n- Căn 3 phòng ngủ: khoảng 91,5–128,3 m²\n- Căn Dual Key\n\nDiện tích mang tính tham khảo và có thể khác nhau giữa các tòa, các phân khu."}, {"heading": "Quy mô dự án", "body": "- Khu đất khoảng 6,14 ha\n- 14 tòa căn hộ và 1 tòa thương mại dịch vụ\n- Các tòa cao 24–29 tầng nổi, 2 tầng hầm\n- Khoảng 3.391 căn hộ"}, {"heading": "Vị trí và tầm nhìn", "body": "Dự án nằm bên bờ sông Hàn, giữa cầu Rồng và cầu Sông Hàn, tiếp giáp các tuyến Trần Hưng Đạo, Ngô Quyền và Nguyễn Công Trứ (phường An Hải, Đà Nẵng). Căn hộ được giới thiệu có ban công hướng về khu vực bắn pháo hoa quốc tế Đà Nẵng.\n\n- Vincom Plaza, cầu Rồng, chợ Cồn: khoảng 5 phút\n- Sân bay quốc tế Đà Nẵng: khoảng 15 phút"}, {"heading": "Pháp lý và chủ đầu tư", "body": "Trang chính thức của dự án công bố sổ đỏ sở hữu lâu dài. Theo CafeLand, Capital Square 2 do Công ty TNHH Mega Assets và Capital Square 3 do Công ty TNHH Bất động sản SIH làm chủ đầu tư.\n\nHãy đối chiếu giấy tờ pháp lý của đúng căn trước khi giao dịch."}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang chính thức capitalsquare.vn và CafeLand, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 0, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/capital-square/khong-gian-thuong-mai', 'PAGE', 'Không gian thương mại tại Capital Square', 'CAPITAL SQUARE · THƯƠNG MẠI', 'Một tòa thương mại dịch vụ cùng trung tâm thương mại Grand Central Mall và tuyến phố Park Boulevard ngay trong dự án.', 'Grand Central Mall và tuyến phố Park Boulevard.', '[{"heading": "Trung tâm thương mại", "body": "Grand Central Mall thuộc phân khu Square District. Quy hoạch dự án có 1 tòa thương mại dịch vụ, bên cạnh 14 tòa căn hộ."}, {"heading": "Tuyến phố Park Boulevard", "body": "Tuyến phố nội khu được chủ đầu tư giới thiệu là khu vực sôi động của dự án, gắn sinh hoạt hằng ngày của cư dân với mua sắm và dịch vụ."}, {"heading": "Kết nối xung quanh", "body": "- Bên bờ sông Hàn, giữa cầu Rồng và cầu Sông Hàn\n- Vincom Plaza, chợ Cồn, Bảo tàng Đà Nẵng: khoảng 5 phút\n- Sân bay quốc tế Đà Nẵng: khoảng 15 phút"}, {"heading": "Thông tin đang cập nhật", "body": "Diện tích từng mặt bằng, giá và hình thức thuê hoặc mua chưa được công bố trong các nguồn chúng tôi có. Hãy liên hệ để được kiểm tra khi có thông tin từ chủ đầu tư."}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang chính thức capitalsquare.vn và CafeLand, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 1, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/capital-square/tien-ich-noi-khu', 'PAGE', 'Tiện ích nội khu tại Capital Square', 'CAPITAL SQUARE · TIỆN ÍCH', 'Quảng trường cảnh quan, bể bơi, phòng tập và các không gian trên tầng thượng dành cho cư dân.', 'Quảng trường, bể bơi, gym và tầng thượng.', '[{"heading": "Không gian ngoài trời", "body": "- Quảng trường trên 2.000 m² tại phân khu Capital State\n- Cảnh quan xanh và sân chơi thể thao\n- Đường chạy bộ nội khu\n- Khu vui chơi trẻ em\n- Khu vườn treo"}, {"heading": "Bể bơi và thư giãn", "body": "- Bể bơi 500 m² và các không gian nghệ thuật tại phân khu Square District\n- Hồ bơi trong nhà và ngoài trời\n- Phòng Gym & Yoga\n- Spa & Sauna"}, {"heading": "Trên tầng thượng", "body": "- Sky Lounge & Rooftop Bar\n- Sky Bar & Café\n- Rooftop Garden\n- Vườn nướng BBQ\n- Vườn cảnh quan đa năng\n- Sân tập Yoga và vườn thiền"}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang chính thức capitalsquare.vn và CafeLand, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn. Danh mục tiện ích có thể khác nhau giữa các tòa."}]'::jsonb, 2, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;
